# - las ventas historicas en estado Parcial (PC) pasan a Pendiente (PE),
#   porque el estado Parcial dejo de existir;
# - las compras que ya tienen fecha de recepcion quedan marcadas como
#   Recibidas (RE) en el nuevo estado logistico.

from django.db import migrations


def normalizar_estados(apps, schema_editor):
    Venta = apps.get_model('app', 'Venta')
    HistoricalVenta = apps.get_model('app', 'HistoricalVenta')
    Compra = apps.get_model('app', 'Compra')
    HistoricalCompra = apps.get_model('app', 'HistoricalCompra')

    Venta.objects.filter(estado='PC').update(estado='PE')
    HistoricalVenta.objects.filter(estado='PC').update(estado='PE')

